import pandas as pd

def tickets_per_team(tickets):
    """Return ticket counts per team, ranked deterministically."""
    counts = tickets.groupby("team").size().rename("n_tickets").reset_index()
    return counts.sort_values(
        ["n_tickets", "team"], ascending=[False, True]
    ).reset_index(drop=True)

import pandas as pd

def courier_stats(deliveries):
    """Return per-courier delivery statistics."""
    stats = deliveries.groupby("courier", as_index=False).agg(
        n=("minutes", "count"),
        avg_minutes=("minutes", "mean"),
        max_minutes=("minutes", "max"),
    )
    stats["avg_minutes"] = stats["avg_minutes"].round(2)
    return stats.sort_values("courier").reset_index(drop=True)

import pandas as pd

def deviation(scores):
    """Return each row's score minus its classroom mean."""
    class_mean = scores.groupby("classroom")["score"].transform("mean")
    return (scores["score"] - class_mean).round(2).rename("dev")

import pandas as pd

def thriving_daily(daily, threshold):
    """Return rows of stores whose mean sales exceed threshold."""
    return daily.groupby("store").filter(
        lambda g: g["sales"].mean() > threshold
    )
